"""Configuration and command-line parsing, using only Python's standard library."""
import os
import re
import json
from pathlib import Path

DEFAULT_LISTS = ['itemize', 'enumerate', 'description', 'inlineroman', 'inventory']
DEFAULT_VERBATIMS = ['verbatim', 'Verbatim', 'lstlisting', 'minted', 'comment']
SHELLS = ['bash', 'elvish', 'fish', 'powershell', 'zsh']
SHORT = dict(zip('cpfnltsvqrhV', ['check', 'print', 'fail-on-change', 'nowrap', 'wraplen', 'tabsize', 'stdin', 'verbose', 'quiet', 'recursive', 'help', 'version']))
VALUE_FLAGS = {'wraplen': 'N', 'tabsize': 'N', 'config': 'PATH', 'completion': 'SHELL'}
BOOL_FLAGS = {'check', 'print', 'fail-on-change', 'nowrap', 'usetabs', 'stdin', 'noconfig', 'verbose', 'quiet', 'trace', 'man', 'args', 'recursive', 'help', 'version'}
ALL_FLAGS = BOOL_FLAGS | VALUE_FLAGS.keys()


class CommandError(Exception):
    pass


def parse_args(arguments, program):
    result, files = {}, []
    args = list(arguments)
    def usage():
        return f'Usage: {program} [OPTIONS] [files]...\n\n'
    def error(msg, showusage=False):
        raise CommandError('error: ' + msg + '\n\n' + (usage() if showusage else '') + "For more information, try '--help'.\n")
    def unexpected(token):
        error(f"unexpected argument '{token}' found\n\n  tip: to pass '{token}' as a value, use '-- {token}'", True)
    def setarg(key, value=None):
        display = '--'+key + (' <'+VALUE_FLAGS[key]+'>' if key in VALUE_FLAGS else '')
        if key in result:
            error(f"the argument '{display}' cannot be used multiple times", True)
        if key in VALUE_FLAGS:
            if value is None:
                error(f"a value is required for '{display}' but none was supplied")
            if key in ('wraplen', 'tabsize'):
                try:
                    if not re.fullmatch(r'\+?[0-9]+', value):
                        raise ValueError()
                    number = int(value)
                except ValueError:
                    reason = 'cannot parse integer from empty string' if not value else 'invalid digit found in string'
                    error(f"invalid value '{value}' for '{display}': {reason}")
                high = 255 if key == 'tabsize' else 65535
                if number > 18446744073709551615:
                    error(f"invalid value '{value}' for '{display}': number too large to fit in target type")
                if number > high:
                    error(f"invalid value '{value}' for '{display}': {value} is not in 0..={high}")
                value = number
            elif key == 'completion' and value not in SHELLS:
                error(f"invalid value '{value}' for '{display}'\n  [possible values: {', '.join(SHELLS)}]")
            result[key] = value
        else:
            result[key] = True
    i = 0
    while i < len(args):
        a = args[i]
        i += 1
        if a == '--':
            files.extend(args[i:]); break
        if a.startswith('--'):
            key, eq, value = a[2:].partition('=')
            if key not in ALL_FLAGS:
                unexpected('--' + key)
            if key in BOOL_FLAGS:
                if eq:
                    error(f"unexpected value '{value}' for '--{key}' found; no more were expected", True)
                setarg(key)
                if key in ('help', 'version'):
                    return result, files
            else:
                if not eq:
                    value = None
                    if i < len(args):
                        if args[i].startswith('-') and args[i] != '-':
                            if args[i] not in ('--help', '-h', '--version', '-V') and not args[i].startswith('--'):
                                unexpected(args[i][:2])
                        else:
                            value = args[i]; i += 1
                setarg(key, value)
