"""Line-oriented TeX formatting, implemented from CLI behavior."""
import re
from collections import deque

# TeX control-word recognition is ASCII-based; delimiters themselves are literal.
ENV_RE = re.compile(r'\\(?:begin\{|end\{|item(?![A-Za-z]))')
ITEM_RE = re.compile(r'\\item(?![A-Za-z])')
COMMENT_RE = re.compile(r'(?<!\\)%')


class Formatter:
    def __init__(self, options, logger):
        self.o = options
        self.log = logger
        self.noindent = set(options['no-indent-envs'])
        self.lists = set(options['lists'])
        self.verbatims = options['verbatims']
        self.wrapchars = set(options['wrap-chars'])

    @staticmethod
    def comment_at(text):
        m = COMMENT_RE.search(text)
        return m.start() if m else len(text)

    def indentation(self, text, initial):
        end = self.comment_at(text)
        code = text[:end]
        current = initial
        visual = initial
        pos = 0
        while pos < len(code):
            if code.startswith('\\begin{', pos) or code.startswith('\\end{', pos):
                begin = code.startswith('\\begin{', pos)
                start = pos + (7 if begin else 5)
                close = code.find('}', start)
                name = code[start:close] if close >= 0 else None
                delta = 0 if name in self.noindent else 2 if name in self.lists else 1
                current += delta if begin else -delta
                visual = min(visual, current)
                # The argument braces are counted along with other delimiters.
                pos = start - 1
            elif code[pos] in '([{':
                current += 1
            elif code[pos] in ')]}':
                current -= 1
                visual = min(visual, current)
            pos += 1
        # An item has one less level of visual indentation, without changing state.
        if ITEM_RE.search(code) and visual != 0:
            visual -= 1
        return current, visual

    def wrap_points(self, text):
        # A space produced by an escaped TeX space must remain with its command.
        # The beginning of a comment isn't a word in its own right.
        prefix = 0
        while prefix < len(text) and text[prefix] in ' %':
            prefix += 1
        points = []
        for i, ch in enumerate(text):
            if ch not in self.wrapchars or i < prefix:
                continue
            if i and text[i-1] == '\\':
                continue
            if not text[i+1:].strip():
                continue
            points.append(i+1)
        return points

    def format(self, source):
        # This reduction is intentionally before trimming lines (space-only blank
        # lines and CRLF blank lines are distinct from runs of LF characters).
        source = re.sub(r'\n{3,}', '\n\n', source)
        if self.o['tabchar'] == 'space':
            source = source.replace('\t', ' ' * self.o['tabsize'])
        lines = source.split('\n')
        if lines and lines[-1] == '':
            lines.pop()
        if not source:
            lines = []
        lines = [line[:-1] if line.endswith('\r') else line for line in lines]
        pending = deque((line, n+1) for n, line in enumerate(lines))
        output = []
        level = 0
        ignore = False
        verbatim = 0
        first_negative = None
        last_zero = 1
        self.log('info', 'Formatting started.')
        while pending:
            original, oldnum = pending.popleft()
            text = original.lstrip()
            num = len(output) + 1
            def event(kind, message, value=text):
                self.log(kind, f'Line {num} ({oldnum}). {message}', value)

            stripped = text.rstrip()
            skip = False
            if stripped.endswith('% tex-fmt: skip'):
                skip = True
            elif stripped.endswith('% tex-fmt: off'):
                if ignore:
                    event('warn', 'Cannot begin ignore block:')
                ignore = True
                skip = True
            elif stripped.endswith('% tex-fmt: on'):
                if not ignore:
                    event('warn', 'No ignore block to end.')
                ignore = False
                skip = True
            if any('\\begin{' + v + '}' in text for v in self.verbatims):
                verbatim += 1
                skip = True
            elif any('\\end{' + v + '}' in text for v in self.verbatims):
                was_verbatim = verbatim > 0
                verbatim -= 1
                skip = skip or was_verbatim
            if verbatim < 0:
                event('warn', 'Verbatim count is negative.')
            if skip or ignore or verbatim > 0:
                output.append(original.rstrip())
                continue

            # Split before every environment/item after the beginning of a line.
            code = text[:self.comment_at(text)]
            inline = next((m.start() for m in ENV_RE.finditer(code) if m.start() > 0), None)
            if inline is not None:
                event('trace', 'Placing environment on new line.')
                pending.appendleft((text[inline:], oldnum))
                text = text[:inline]

            # Wrapped fragments are re-processed from the state at the start of
            # the original line, since a split can separate balanced delimiters.
            while True:
                actual, visual = self.indentation(text, level)
                event('trace', f'Indent: actual = {actual}, visual = {visual}:', text)
                if visual < 0:
                    event('warn', 'Indent is negative.', text)
                    if first_negative is None:
                        first_negative = num
                elif visual == 0:
                    last_zero = num
                indentlen = max(visual, 0) * self.o['tabsize']
                if self.o['wrap'] and len(text) + indentlen > self.o['wraplen']:
                    event('trace', 'Wrapping long line.', text)
                    points = self.wrap_points(text)
                    before = [p for p in points if p <= max(0, self.o['wrapmin'] - indentlen)]
                    split = before[-1] if before else points[0] if points else None
                    if split is None or split - 1 + indentlen > self.o['wraplen']:
                        event('warn', 'Line cannot be wrapped.', text)
                    if split is not None:
                        head, tail = text[:split], text[split:].lstrip()
                        if self.comment_at(head) < len(head):
                            tail = '% ' + tail
                        pending.appendleft((tail, oldnum))
                        text = head
                        continue
                pad = ('\t' if self.o['tabchar'] == 'tab' else ' ') * indentlen
                output.append((pad + text).rstrip())
                level = actual
                break
        if level != 0:
            self.log('warn', f'Indent does not return to zero. Last non-indented line is line {last_zero}')
        if first_negative is not None:
            self.log('warn', f'Negative indents. First negatively indented line is line {first_negative}')
        self.log('info', 'Formatting complete.')
        return '\n'.join(output).rstrip() + '\n'
