#!/usr/bin/env python3
"""Standalone entry point for the independently implemented formatter."""
import os
import sys
import re
import pkgutil
import fnmatch
from pathlib import Path
from formatter import Formatter
from settings import parse_args, resolve, describe, CommandError, ConfigError

LEVELS = {'error':0,'warn':1,'info':2,'trace':3}


def asset(name):
    return pkgutil.get_data('assets', name+'.txt').decode('utf-8')


def logger(verbosity, name=''):
    maximum = LEVELS.get(verbosity, 1)
    def emit(level, msg, detail=''):
        if LEVELS[level] <= maximum:
            sys.stderr.write(f'{level.upper()}: tex-fmt {name}: {msg} {detail}\n')
    return emit


